def top_k_sample(distribution, k):
    # already covered as keeping only the top k words in this topic
    sorted_items = sorted(distribution.items(), key=lambda item: item[1], reverse=True)
    top_k_items = sorted_items[:k]

    # already covered as renormalizing after restriction in this topic
    total = sum(prob for _, prob in top_k_items)
    renormalized = {word: prob / total for word, prob in top_k_items}
    return renormalized

distribution = {
    "mat": 0.35, "rug": 0.25, "floor": 0.15,
    "chair": 0.1, "table": 0.08, "wall": 0.07,
}

for k in [2, 4]:
    # already covered as choosing k value in this topic
    result = top_k_sample(distribution, k)
    print(f"k={k}: {result}")
